if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !case <text>\n\nAlso works with: !upper <text>, !lower <text>');
const text = argumentName;
const trigger = msg.message?.conversation || msg.message?.extendedTextMessage?.text || '';
const cmd = trigger.split(/\s+/)[0].replace(/^[^a-zA-Z]/, '').toLowerCase();
let result;
if (cmd === 'upper') {
  result = text.toUpperCase();
} else if (cmd === 'lower') {
  result = text.toLowerCase();
} else {
  result = 'UPPER: ' + text.toUpperCase() + '\n\nlower: ' + text.toLowerCase() + '\n\ntitle: ' + text.replace(/\b\w/g, c => c.toUpperCase()) + '\n\nswap: ' + text.split('').map((c, i) => i % 2 === 0 ? c.toUpperCase() : c.toLowerCase()).join('');
}
await sendTrackedMessage(sock, remoteJid, result);
